 {compare&&displayedA&&displayedB&&<><div className="compare-dates"><span>Date A · {formatDate(displayedA!.date,{month:'short',day:'numeric',year:'numeric'})}</span><span>Date B · {formatDate(displayedB!.date,{month:'short',day:'numeric',year:'numeric'})}</span></div>{compareMode==='lens'?<button className="change-lens" style={{left:`${lens.x}%`,top:`${lens.y}%`}} aria-label="Move change lens; use arrow keys or drag to inspect the newer capture" onPointerDown={event=>event.currentTarget.setPointerCapture(event.pointerId)} onPointerMove={moveLens} onKeyDown={event=>{if(!event.key.startsWith('Arrow'))return;event.preventDefault();setLens(p=>({x:Math.max(5,Math.min(95,p.x+(event.key==='ArrowRight'?3:event.key==='ArrowLeft'?-3:0))),y:Math.max(15,Math.min(80,p.y+(event.key==='ArrowDown'?3:event.key==='ArrowUp'?-3:0)))}))}}><span>{formatDate(displayedB.date,{month:"short",day:"numeric",year:"numeric"})} · drag to inspect</span></button>:<><div className="swipe-divider" style={{left:`${split}%`}}><span><ChevronLeft size={15}/><ChevronRight size={15}/></span></div><input className="swipe-input" type="range" min="10" max="90" value={split} onChange={e=>setSplit(+e.target.value)} aria-label="Capture comparison divider"/></>}</>}

